package net.officefloor.hq.app.pool;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class AddPool {
    public void add(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val PoolRequest request, SheetRepository sheets, PoolRepository pools, Out<PoolAdded> added) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        sheets.open(id, user);
        pools.add(id, request.name(), user);
        added.set(new PoolAdded(id, request.name(), user));
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Adds a person of the sheet, or another pool of the sheet, to the pool with a share percent (at most two
 *  decimals, more than 0.00 and at most 100.00): refused (nothing written) for no such pool or person, a
 *  person already in the pool, or a bad share; and for a pool that is already a member of a pool, that
 *  would contain itself through any chain, or that would make a chain of pools more than three deep. */
public class AddPoolMember {

    private static final Pattern SHARE = Pattern.compile("\\d+(\\.\\d{1,2})?");

    private static final BigDecimal MAX = new BigDecimal("100.00");

    /** The most pools in a chain, the one a member of none counting as the first. */
    private static final int MAX_DEPTH = 3;

    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") long poolId,
            @RequestParam(name = "by", required = false) String by, @RequestBody PoolMemberRequest request,
            PoolRepository pools, PersonRepository people, Out<PoolMemberAdded> added)
            throws InvalidPoolException {
        String id = sheetId.trim();
        String pool = pools.nameOf(id, poolId);
        if (pool == null) {
            throw new InvalidPoolException("No such pool: " + poolId);
        }
        if (request == null || (request.personId() == null && request.memberPoolId() == null)) {
            throw new InvalidPoolException("No member named");
        }
        Person person = null;
        String memberPool = null;
        if (request.personId() != null) {
            person = people.find(id, request.personId());
            if (person == null) {
                throw new InvalidPoolException("No such person on the sheet: " + request.personId());
            }
        } else {
            memberPool = pools.nameOf(id, request.memberPoolId());
            if (memberPool == null) {
                throw new InvalidPoolException("No such pool on the sheet: " + request.memberPoolId());
            }
        }
        String text = request.share() == null ? "" : request.share().trim();
        if (!SHARE.matcher(text).matches()) {
            throw new InvalidPoolException("A share is a percent with at most two decimals");
        }
        BigDecimal share = new BigDecimal(text).setScale(2);
        if (share.signum() <= 0 || share.compareTo(MAX) > 0) {
            throw new InvalidPoolException("A share is more than 0.00 and at most 100.00");
        }
        String user = by == null ? "" : by;
        if (person != null) {
            if (pools.hasMember(poolId, person.getId())) {
                throw new InvalidPoolException(person.getName() + " is already in " + pool);
            }
            pools.addMember(id, poolId, person.getId(), share, user);
            added.set(new PoolMemberAdded(id, pool, person.getName(), share.toPlainString(), user));
            return;
        }
        long child = request.memberPoolId();
        int level = 0;
        for (Long above = poolId; above != null && level <= MAX_DEPTH; above = pools.parentOf(above)) {
            if (above == child) {
                throw new InvalidPoolException(memberPool + " cannot contain itself");
            }
            level++;
        }
        if (pools.parentOf(child) != null) {
            throw new InvalidPoolException(memberPool + " is already a member of a pool");
        }
        if (level + height(pools, child, 1) > MAX_DEPTH) {
            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep");
        }
        pools.addPoolMember(id, poolId, child, share, user);
        added.set(new PoolMemberAdded(id, pool, memberPool, share.toPlainString(), user));
    }

    /** The most pools in a chain down from {@code poolId}, itself counting as one (stops past the limit). */
    private static int height(PoolRepository pools, long poolId, int depth) {
        int most = 1;
        if (depth > MAX_DEPTH) return most;
        for (long below : pools.childrenOf(poolId)) {
            most = Math.max(most, 1 + height(pools, below, depth + 1));
        }
        return most;
    }
}
package net.officefloor.hq.app.pool;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPool {
    public void handle(@Parameter InvalidPoolException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.pool;

/** The pool's name is blank or already used on the sheet, or the member is already in the pool, not on
 *  the sheet, or has a share that is not more than 0.00 and at most 100.00 with two decimals: refused
 *  and nothing is written. Also a member pool already a member of a pool, that would contain itself through
 *  a chain, or that would make a chain of pools more than three deep. */
public class InvalidPoolException extends Exception {
    public InvalidPoolException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class ListPools {
    public void list(@PathVariable("sheetId") String sheetId, PoolRepository pools,
            ObjectResponse<List<Pool>> response) {
        response.send(pools.list(sheetId.trim()));
    }
}
package net.officefloor.hq.app.pool;

/** A pool that went through, and who added it. */
public record PoolAdded(String sheetId, String name, String by) {
}
package net.officefloor.hq.app.pool;

import java.util.List;

/** A pool on a sheet, its members (in the order they were added), the total of their shares (a retired
 *  member's counting as 0.00) and whether that total is exactly 100.00. {@code parentId} is the pool it is a
 *  member of (null: none); its pot is then its cut there, else the sheet's pot. */
public record Pool(long id, String sheetId, String name, List<PoolMember> members, String totalShare,
        boolean balanced, Long parentId) {
}
package net.officefloor.hq.app.pool;

/** A member added to a pool that went through, and who added it. */
public record PoolMemberAdded(String sheetId, String pool, String name, String share, String by) {
}
package net.officefloor.hq.app.pool;

/** A member of a pool, with their share percent (two decimals) and their cut of the pool's pot (two
 *  decimals; "" when the pool is unbalanced or has no pot). The member is a person ({@code personId},
 *  {@code poolId} null; {@code retired} when they are) or another pool ({@code poolId}, {@code personId}
 *  null; {@code name} the pool's name; never retired). */
public record PoolMember(Long personId, Long poolId, String name, String share, boolean retired, String cut) {

    public PoolMember withCut(String cut) {
        return new PoolMember(personId, poolId, name, share, retired, cut);
    }
}
package net.officefloor.hq.app.pool;

/** Body of adding a member to a pool: the person, or else the pool ({@code memberPoolId}), and their share
 *  percent as typed. */
public record PoolMemberRequest(Long personId, Long memberPoolId, String share) {
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PoolRepository {

    private static final BigDecimal FULL = new BigDecimal("100.00");

    private static final BigDecimal HUNDRED = new BigDecimal("100");

    private final JdbcTemplate jdbc;
    private final SettingRepository settings;

    public PoolRepository(JdbcTemplate jdbc, SettingRepository settings) {
        this.jdbc = jdbc;
        this.settings = settings;
    }

    /** The sheet's pools in the order they were added, each with its members in the order they were added.
     *  A pool that is a member of none cuts the sheet's pot; one that is a member of another cuts its cut
     *  there (none when that pool has no cuts). */
    public List<Pool> list(String sheetId) {
        Map<Long, String> names = new LinkedHashMap<>();
        Map<Long, List<PoolMember>> members = new LinkedHashMap<>();
        Map<Long, Long> parents = new HashMap<>();
        jdbc.query("SELECT id, name FROM pool WHERE sheet_id = ? ORDER BY id", rs -> {
            names.put(rs.getLong("id"), rs.getString("name"));
            members.put(rs.getLong("id"), new ArrayList<>());
        }, sheetId);
        jdbc.query("SELECT m.pool_id, m.person_id, m.member_pool_id, COALESCE(p.name, q.name) AS name, m.share, "
                + "p.retired_from FROM pool_member m LEFT JOIN person p ON p.id = m.person_id "
                + "LEFT JOIN pool q ON q.id = m.member_pool_id WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
                    List<PoolMember> of = members.get(rs.getLong("pool_id"));
                    if (of != null) {
                        Long personId = rs.getObject("person_id") == null ? null : rs.getLong("person_id");
                        Long poolId = rs.getObject("member_pool_id") == null ? null : rs.getLong("member_pool_id");
                        if (poolId != null) parents.put(poolId, rs.getLong("pool_id"));
                        of.add(new PoolMember(personId, poolId, rs.getString("name"),
                                rs.getBigDecimal("share").setScale(2).toPlainString(),
                                rs.getObject("retired_from") != null, ""));
                    }
                }, sheetId);
        BigDecimal pot = settings.pot(sheetId);
        Map<Long, BigDecimal> totals = new HashMap<>();
        for (Map.Entry<Long, List<PoolMember>> pool : members.entrySet()) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (PoolMember m : pool.getValue()) {
                if (!m.retired()) total = total.add(new BigDecimal(m.share()));
            }
            totals.put(pool.getKey(), total);
        }
        Map<Long, List<PoolMember>> cut = new HashMap<>();
        for (Long id : names.keySet()) cutOf(id, members, parents, totals, pot, cut, new HashSet<>());
        List<Pool> pools = new ArrayList<>();
        for (Map.Entry<Long, String> pool : names.entrySet()) {
            BigDecimal total = totals.get(pool.getKey());
            pools.add(new Pool(pool.getKey(), sheetId, pool.getValue(), cut.get(pool.getKey()),
                    total.toPlainString(), total.compareTo(FULL) == 0, parents.get(pool.getKey())));
        }
        return pools;
    }

    /** The pool's members with their cuts, worked out (and kept in {@code cut}) after those of the pool above
     *  it: its pot is the sheet's pot when it is a member of none, else its cut in the pool above. */
    private static List<PoolMember> cutOf(Long id, Map<Long, List<PoolMember>> members, Map<Long, Long> parents,
            Map<Long, BigDecimal> totals, BigDecimal sheetPot, Map<Long, List<PoolMember>> cut, Set<Long> seen) {
        List<PoolMember> done = cut.get(id);
        if (done != null) return done;
        List<PoolMember> of = members.get(id);
        BigDecimal pot = null;
        Long parent = parents.get(id);
        if (parent == null) {
            pot = sheetPot;
        } else if (seen.add(id) && members.containsKey(parent)) {
            for (PoolMember m : cutOf(parent, members, parents, totals, sheetPot, cut, seen)) {
                if (id.equals(m.poolId()) && !m.cut().isEmpty()) pot = new BigDecimal(m.cut());
            }
        }
        List<PoolMember> result = pot != null && totals.get(id).compareTo(FULL) == 0 ? cut(of, pot) : of;
        cut.put(id, result);
        return result;
    }

    /** The members with their cuts of the pot: the pot times their share over 100, rounded half to even
     *  to two decimals (a retired member's 0.00); the remainder goes to the member with the largest share
     *  (the earliest added on a tie), so the cuts total exactly the pot. */
    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot) {
        BigDecimal[] cuts = new BigDecimal[members.size()];
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int largest = -1;
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            BigDecimal share = new BigDecimal(m.share());
            cuts[i] = m.retired() ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(share).divide(HUNDRED).setScale(2, RoundingMode.HALF_EVEN);
            sum = sum.add(cuts[i]);
            if (!m.retired() && (largest < 0 || share.compareTo(new BigDecimal(members.get(largest).share())) > 0)) {
                largest = i;
            }
        }
        if (largest >= 0) cuts[largest] = cuts[largest].add(pot.subtract(sum));
        List<PoolMember> cut = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) cut.add(members.get(i).withCut(cuts[i].toPlainString()));
        return cut;
    }

    public boolean contains(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool WHERE sheet_id = ? AND name = ?",
                Integer.class, sheetId, name);
